import React from 'react'

import ChevronRightIcon from '@mui/icons-material/ChevronRight'
import CloseIcon from '@mui/icons-material/Close'
import ExpandMoreIcon from '@mui/icons-material/ExpandMore'
import VisibilityIcon from '@mui/icons-material/Visibility'
import VisibilityOffIcon from '@mui/icons-material/VisibilityOff'
import Chip from '@mui/material/Chip'
import IconButton from '@mui/material/IconButton'
import Link from '@mui/material/Link'
import Tooltip from '@mui/material/Tooltip'
import Typography from '@mui/material/Typography'
import { observer } from 'mobx-react'
import {
  LOW_IDENTITY_OVER_SHORTER,
  SHORT_ALIGNMENT_IDENTITY,
  SHORT_ALIGNMENT_RESIDUES,
  describeAlignmentQuality,
  describeCoveredRange,
  describeTranscriptCoverage,
  isLowSimilarity,
  uniprotEntryUrl,
} from 'p2s_mapper'

import ChainSelect from './ChainSelect'
import { describeCoverage } from '../describeCoverage'

import type {
  JBrowsePluginProteinStructureModel,
  JBrowsePluginProteinViewModel,
} from '../model'

const LOW_SIMILARITY_EXPLANATION = `Under ${Math.round(
  LOW_IDENTITY_OVER_SHORTER * 100,
)}% of the shorter sequence is identical (${Math.round(
  SHORT_ALIGNMENT_IDENTITY * 100,
)}% for an alignment of fewer than ${SHORT_ALIGNMENT_RESIDUES} residues): an alignment this weak is what two unrelated proteins produce, so the positions it maps may be unrelated. Check the mapped chain, the transcript isoform, or import a curated alignment.`

// Which UniProt entry the structure's mapped chain is, and so which one its
// feature tracks annotate. For an AlphaFold model that is in the filename, but
// for a PDB entry it is resolved via SIFTS and is otherwise invisible.
const UniProtLink = observer(function UniProtLink({
  structure,
}: {
  structure: JBrowsePluginProteinStructureModel
}) {
  const { uniprotId, uniprotName } = structure.uniProtEntry
  return uniprotId ? (
    <Tooltip
      title={`The mapped chain is UniProt ${uniprotId}${uniprotName ? ` (${uniprotName})` : ''}, which its feature tracks annotate`}
    >
      <Link
        variant="caption"
        href={uniprotEntryUrl(uniprotId)}
        target="_blank"
        rel="noreferrer"
        noWrap
        sx={{ minWidth: 40 }}
      >
        UniProt {uniprotId}
      </Link>
    </Tooltip>
  ) : null
})

const StructureRow = observer(function StructureRow({
  model,
  structure,
  readout,
}: {
  model: JBrowsePluginProteinViewModel
  structure: JBrowsePluginProteinStructureModel
  readout: string
}) {
  const { label, alignmentQuality: quality, statusMessage, hidden } = structure
  const several = model.structures.length > 1
  const switchable = model.showAlignment && several
  const open = model.alignmentStructure === structure
  const coveredRange = quality ? describeCoveredRange(quality) : undefined
  return (
    // data-label rather than data-structure: that one names the alignment
    // panel, and a selector matching both finds whichever the DOM has first
    <div
      data-testid="structure-row"
      data-label={label}
      data-open={switchable ? open : undefined}
      data-hidden={hidden || undefined}
      style={{
        opacity: hidden ? 0.6 : undefined,
        display: 'flex',
        alignItems: 'center',
        gap: 8,
        minHeight: 24,
        minWidth: 0,
      }}
    >
      {switchable ? (
        <Tooltip title={open ? 'Alignment shown below' : 'Show alignment'}>
          <span>
            <IconButton
              size="small"
              aria-label={`Show ${label} alignment`}
              aria-expanded={open}
              disabled={open}
              onClick={() => {
                model.openAlignmentOf(structure)
              }}
              sx={{ p: 0 }}
            >
              {open ? (
                <ExpandMoreIcon fontSize="small" />
              ) : (
                <ChevronRightIcon fontSize="small" />
              )}
            </IconButton>
          </span>
        </Tooltip>
      ) : null}
      <Typography variant="caption" sx={{ fontWeight: 'bold', flexShrink: 0 }}>
        {label}
      </Typography>
      {statusMessage ? (
        <Typography
          variant="caption"
          color="error"
          data-testid="structure-status"
        >
          {statusMessage}
        </Typography>
      ) : null}
      {readout ? (
        <Typography
          variant="caption"
          noWrap
          title={readout}
          data-testid="structure-hover"
        >
          {readout}
        </Typography>
      ) : quality ? (
        <Tooltip
          title={
            quality.aligned === 0
              ? ''
              : `${describeTranscriptCoverage(quality)}${coveredRange ? `, ${coveredRange}` : ''}; ${describeAlignmentQuality(quality)}`
          }
        >
          <Typography
            variant="caption"
            color="textSecondary"
            noWrap
            data-testid="header-alignment-quality"
          >
            {describeCoverage(quality)}
          </Typography>
        </Tooltip>
      ) : null}
      <UniProtLink structure={structure} />
      <div style={{ flex: 1 }} />
      {model.offersChainPicker(structure) ? (
        <ChainSelect model={structure} />
      ) : null}
      {quality && isLowSimilarity(quality) ? (
        <Tooltip title={LOW_SIMILARITY_EXPLANATION}>
          <Chip
            size="small"
            color="warning"
            variant="outlined"
            label="low similarity"
            data-testid="header-low-similarity"
          />
        </Tooltip>
      ) : null}
      {several || hidden ? (
        <Tooltip title={hidden ? `Show ${label}` : `Hide ${label}`}>
          <IconButton
            size="small"
            aria-label={hidden ? `Show ${label}` : `Hide ${label}`}
            aria-pressed={hidden}
            onClick={() => {
              structure.setHidden(!hidden)
            }}
            sx={{ p: 0.25 }}
          >
            {hidden ? (
              <VisibilityOffIcon fontSize="small" />
            ) : (
              <VisibilityIcon fontSize="small" />
            )}
          </IconButton>
        </Tooltip>
      ) : null}
      <Tooltip title={`Remove ${label}`}>
        <IconButton
          size="small"
          aria-label={`Remove ${label}`}
          onClick={() => {
            model.removeStructure(structure)
          }}
          sx={{ p: 0.25 }}
        >
          <CloseIcon fontSize="small" />
        </IconButton>
      </Tooltip>
    </div>
  )
})

/**
 * One line per structure, in the header the reader always sees. The identity
 * and coverage readout used to live only inside the pairwise panel, which the
 * same reader can hide — so how much of the transcript a structure speaks for,
 * and whether the mapping is chance, were one click away from invisible. A row
 * also carries what used to head the alignment panel, the mapped-chain picker:
 * the open structure's row, or every row while the panel is hidden.
 *
 * A hovered residue is read out on its structure's row, in place of the
 * coverage line until the pointer leaves. A genome or MSA hover that reaches
 * one mapped structure but not another says so, since a crystal that lacks
 * the residue is the point of showing several.
 */
const HeaderStructureRows = observer(function HeaderStructureRows({
  model,
}: {
  model: JBrowsePluginProteinViewModel
}) {
  const { structures } = model
  const connectedHover = structures.some(
    s => s.hoverPosition && s.hoverPosition.source !== 'structure',
  )
  return (
    <div style={{ flex: 1, minWidth: 0 }}>
      {structures.map((structure, idx) => (
        <StructureRow
          key={idx}
          model={model}
          structure={structure}
          readout={
            structure.hoverString ||
            (connectedHover && structure.genomeToTranscriptSeqMapping
              ? 'not in structure'
              : '')
          }
        />
      ))}
    </div>
  )
})

export default HeaderStructureRows
